ls -lh /work/output/artifacts/skill-bpmn-registry-discovery/registry-evidence/ && echo "---" && python3 -c "
import json, pathlib
for f in sorted(pathlib.Path('/work/output/artifacts/skill-bpmn-registry-discovery/registry-evidence').iterdir()):
    raw = f.read_text()
    try:
        d = json.loads(raw)
        print(f.name, '| Result:', d.get('Result'), '| Code:', d.get('Code'), '| Data keys:', list((d.get('Data') or {}).keys())[:6])
    except Exception as e:
        print(f.name, 'PARSE ERROR', e)
